using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using LastRail.Battle;
using LastRail.Auth;
using LastRail.Run;
using System.Threading.Tasks;
namespace LastRail.Tests.EditMode {
 public sealed class BNamedOperatorSourceTests {
  internal static JObject Packet()=> (JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-named-operator-source-local-refit-sample-20261004.json"))["packet"];
  internal static BNamedOperatorSource Source(){var p=Packet();return BNamedOperatorSource.Read(p,p,"0537f57c0ccdba49fe891ccc58b895d2ad8321aca1a96c3dead2cff83b7f198f");}
  [Test] public void OriginalNamedSourceKeepsMissingFieldsAndBothSuppliedStats(){var s=Source();Assert.AreEqual(1400,(int)s.Actor("op_kyle")["permanentStats"]["maxHp"]);Assert.AreEqual(1600,(int)s.Actor("op_sable")["permanentStats"]["maxHp"]);Assert.AreEqual(JTokenType.Null,s.Actor("op_sable")["equipment"].Type);var p=s.Capture();p["actors"][0]["permanentStats"]["maxHp"]=1;Assert.AreEqual(1400,(int)s.Actor("op_kyle")["permanentStats"]["maxHp"]);}
  [TestCase("unknown")][TestCase("stat")][TestCase("timing")][TestCase("version")]
  public void CallerCannotRehashChangedSourceToAuthorizeIt(string fault){var original=Packet();var p=(JObject)original.DeepClone();if(fault=="unknown")p["unknown"]=1;if(fault=="stat")p["actors"][0]["permanentStats"]["maxHp"]=999999;if(fault=="timing")p["actors"][0]["interception"]["acceptedTiming"]=new JObject();if(fault=="version")p["version"]="old";Assert.Throws<ArgumentException>(()=>BNamedOperatorSource.Read(p,original,(string)original["packetHash"]));}
  [Test] public void NewNativeBranchMustBeExplicit(){Assert.NotNull(typeof(BNamedOperatorNativeAdapter).GetMethod("ReadNamedSource"),"new source must not expand old C3 roster or alias Sable");}
  sealed class Transport:IGameApiAuthenticatedHttpTransport {
   public RunApiHttpRequest Request;public GameApiAccessToken Token;public GameApiAuthenticatedHttpResult Result;
   public Task<GameApiAuthenticatedHttpResult> SendAsync(RunApiHttpRequest r,GameApiAccessToken t){Request=r;Token=t;return Task.FromResult(Result);}
  }
  [Test] public async Task AuthenticatedApiUsesExactContractAndCapturesIndependentOriginal(){var p=Packet();var t=new Transport{Result=GameApiAuthenticatedHttpResult.Succeeded(RunApiHttpResponse.Success(200,p.ToString(),new[]{new RunApiHttpHeader("ETag",(string)p["packetHash"])}))};var token=new GameApiAccessToken("lst1.local-test-only");var value=await new BNamedOperatorSourceHttpClient(t).CaptureAsync(new[]{"op_kyle","op_sable"},1,1,token);Assert.AreSame(token,t.Token);Assert.AreEqual("POST",t.Request.Method);Assert.AreEqual("/v1/combat/b-named-operator-source",t.Request.EndpointPath);Assert.AreEqual(BNamedOperatorSource.Version,t.Request.Headers.Single(h=>h.Name=="X-B-Named-Operator-Version").Value);Assert.AreEqual(3,JObject.Parse(t.Request.BodyJson).Count);Assert.IsTrue(JToken.DeepEquals(p,value.Capture()));}
  [Test] public void AuthRequiredDoesNotCreateSourceOrRetryMutation(){var t=new Transport{Result=GameApiAuthenticatedHttpResult.AuthRequired(RunApiHttpResponse.Success(401,"{}"),"session_expired",null)};Assert.ThrowsAsync<InvalidOperationException>(async()=>await new BNamedOperatorSourceHttpClient(t).CaptureAsync(new[]{"op_sable"},1,1,new GameApiAccessToken("lst1.local-test-only")));}
  internal static (BNamedOperatorNativeAdapter adapter,BDirectAttackBasicLoopBinding binding) Native(BNamedOperatorSource supplied=null){
   var s=supplied??Source();var receipt=BInterceptSourceTests.Read(BInterceptSourceTests.Sample());var old=BOrdinaryGeometryTests.Stress(BInterceptSourceTests.Sample());var p=old.Composition.Attack.Capture();var d=(JObject)s.Capture()["refit"]["departure"];var form=new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,((JArray)d["cars"]).Select(c=>new BCombatSlot((string)c["instanceId"],(string)c["occupant"]["operatorId"])).ToArray());
   p["formation"]=form.Capture();var entities=(JArray)p["entities"];var car=(JObject)entities.Single(e=>(string)e["kind"]=="CARRIAGE");car["id"]=form.Slots[0].CarriageId;var second=(JObject)car.DeepClone();second["id"]=form.Slots[1].CarriageId;second["slot"]=1;entities.Add(second);var k=(JObject)entities.Single(e=>(string)e["id"]=="op_kyle");var sable=(JObject)k.DeepClone();sable["id"]="op_sable";sable["definitionId"]="op_sable";sable["slot"]=1;entities.Add(sable);
   // Explicit LOCAL test range only; the supplier's missing range remains null.
   p["geometry"]=new JArray(entities.Where(e=>(string)e["kind"]=="LOCAL_ENEMY").SelectMany(e=>new[]{"op_kyle","op_sable"}.Select((id,slot)=>new JObject{["sourceId"]=id,["targetId"]=e["id"].DeepClone(),["sourceSlot"]=slot,["targetSlot"]=e["slot"].DeepClone(),["distanceMm"]=0,["maximumDistanceMm"]=1800,["observedTick"]=0,["validUntilTick"]=1000000,["eligible"]=false})));
   var a=BNamedOperatorNativeAdapter.ReadNamedSource(p,BDirectAttackInput.Digest(p),s,BNamedOperatorNativeAdapterTests.Definition(),form,receipt.OriginalSource,BInterceptSourceTests.Defs());var c=old.Composition.Capture();c["attackInputHash"]=a.Input.OriginalHash;c["departure"]=d;c["initial"]["cars"]=new JArray(new[]{0,1}.Select(i=>new JObject{["slot"]=i,["body"]="NORMAL",["actor"]="UP"}));var composition=new BDirectAttackBuffBinding(a.Input,old.Composition.Definitions,c,BDirectAttackInput.Digest(c));var routes=old.Capture();routes["compositionHash"]=composition.OriginalHash;foreach(string id in new[]{"op_kyle","op_sable"})((JArray)routes["targets"]).Add(new JObject{["sourceId"]=id,["targetId"]=entities.First(e=>(string)e["kind"]=="LOCAL_ENEMY")["id"].DeepClone()});
   return (a,new BDirectAttackBasicLoopBinding(composition,routes,BDirectAttackInput.Digest(routes)));
  }
  [Test] public void ActualTwoNamedActorsUseOriginalNativeHpAndReplay(){var f=Native();var g=BOrdinaryGeometryTests.Geometry(f.binding);var n=f.adapter.CreateRuntime(f.binding,g,10000);Assert.AreEqual(1400,n.Hp("op_kyle"));Assert.AreEqual(1600,n.Hp("op_sable"));n.Advance("original-native",10000000,500);var state=n.Capture();var restored=BDirectAttackBasicLoop.RestoreOrdinaryGeometryRuntime(state,BDirectAttackInput.Digest(state),f.binding,BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource,g,10000,false);Assert.IsTrue(JToken.DeepEquals(state,restored.Capture()));}
  [Test] public void SableActuallyAttacksThroughNativePeriodOwner(){var f=Native();var g=BOrdinaryGeometryTests.Geometry(f.binding,BOrdinaryGeometryTests.ShortCarAsset());var n=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(f.binding,BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource,g,10000,true);n.MoveOrdinaryOperator("local-sable-probe","op_sable",0,new JArray(0,2400,0),g.Hash);var hits=new System.Collections.Generic.List<BDirectAttackBuffReceipt>();for(int i=0;i<15;i++)hits.AddRange(n.Advance("native-sable-"+i,10000000,500).Hits.Where(h=>h.Attack.SourceId=="op_sable"));Assert.That(hits.Count,Is.GreaterThanOrEqualTo(2));Assert.That(hits[0].Attack.Hp.HpLoss,Is.GreaterThan(0).And.LessThanOrEqualTo(32));Assert.AreEqual(1000,hits[1].Attack.Tick-hits[0].Attack.Tick);Assert.AreEqual(2000000,(long)f.adapter.Input.Capture()["entities"].Single(e=>(string)e["id"]=="op_sable")["basicIntervalMicroseconds"]);File.WriteAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/NamedOperatorAdapter/native-sable-basic.json",n.Capture().ToString());}
  [TestCase("rank")][TestCase("type")]
  public void ChangedOtherwiseValidRefitCannotChangeOriginalInterceptionOwner(string field){var f=Native();var c=f.binding.Composition.Capture();if(field=="rank")foreach(var car in c["departure"]["cars"])car["rank"]=2;else c["departure"]["cars"][0][field]="BCB01";var composition=new BDirectAttackBuffBinding(f.adapter.Input,f.binding.Composition.Definitions,c,BDirectAttackInput.Digest(c));var routes=f.binding.Capture();routes["compositionHash"]=composition.OriginalHash;var changed=new BDirectAttackBasicLoopBinding(composition,routes,BDirectAttackInput.Digest(routes));var g=BOrdinaryGeometryTests.Geometry(changed);StringAssert.Contains("original_refit_conflict",Assert.Throws<ArgumentException>(()=>f.adapter.CreateRuntime(changed,g,10000)).Message);}
 }
}
